    return segments.map((s) => (s.kind === 'empty' ? EMPTY_GLYPH.repeat(s.count) : s.text)).join('');
}
/** `dim` is an explicit grey: SGR 2 is nearly invisible in some hosts' footers. */
const FG = { green: '32', yellow: '33', red: '31', dim: '38;5;245', cyan: '36' };
